// Node 2: Input Validation & Sanitization
const input = $input.first().json.body || $input.first().json;

if (!input || typeof input !== 'object') {
  throw new Error('Invalid payload: Request body must be a valid JSON object.');
}

const requiredFields = ['projectCategory', 'projectName', 'projectDescription', 'contactEmail'];
const missing = requiredFields.filter(f => !input[f] || (typeof input[f] === 'string' && input[f].trim().length === 0));

if (missing.length > 0) {
  return [{
    json: {
      isValid: false,
      error: `Missing required field(s): ${missing.join(', ')}`,
      status: 400
    }
  }];
}

// Email validation regex
const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/;
if (!emailRegex.test(input.contactEmail)) {
  return [{
    json: {
      isValid: false,
      error: 'Invalid contact email format provided.',
      status: 400
    }
  }];
}

// Anti-prompt injection & string sanitization
function sanitizeText(str) {
  if (!str || typeof str !== 'string') return '';
  return str
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/\b(ignore all previous instructions|system prompt|disregard previous)\b/gi, '[filtered_command]')
    .trim();
}

const sanitizedInput = {
  projectCategory: sanitizeText(input.projectCategory),
  projectName: sanitizeText(input.projectName),
  projectDescription: sanitizeText(input.projectDescription),
  targetAudience: sanitizeText(input.targetAudience || 'General Users'),
  industryNiche: sanitizeText(input.industryNiche || 'Technology'),
  expectedOutcome: sanitizeText(input.expectedOutcome || ''),
  dynamicFields: input.dynamicFields || {},
  complexity: input.complexity || 'Moderate',
  targetTimeline: sanitizeText(input.targetTimeline || 'Standard (6-8 weeks)'),
  budgetRange: sanitizeText(input.budgetRange || 'Flexible'),
  preferredTechStack: sanitizeText(input.preferredTechStack || 'Modern Agency Recommended (Next.js, Tailwind, Node/Python)'),
  contactName: sanitizeText(input.contactName || 'Valued Client'),
  contactEmail: input.contactEmail.trim().toLowerCase(),
  companyName: sanitizeText(input.companyName || ''),
  currency: (input.currency || 'USD').toUpperCase()
};

return [{
  json: {
    isValid: true,
    data: sanitizedInput
  }
}];

// Node 4: Requirement Normalization & WBS Base Engine
const item = $input.first().json.data;

// Heuristic Base Hours Mapping by Vertical
const verticalBaseHours = {
  'website development': 60,
  'e-commerce development': 120,
  'saas development': 160,
  'ai system development': 140,
  'ai chatbot': 80,
  'ai voice agent': 110,
  'crm / management system': 130,
  'workflow automation': 50,
  'mobile application': 150,
  'custom software': 140
};

const catKey = item.projectCategory.toLowerCase();
let baseHours = 100;
for (const [key, val] of Object.entries(verticalBaseHours)) {
  if (catKey.includes(key)) {
    baseHours = val;
    break;
  }
}

// Complexity Multipliers
let complexityMultiplier = 1.0;
if (item.complexity.toLowerCase().includes('simple') || item.complexity.toLowerCase().includes('mvp')) {
  complexityMultiplier = 0.85;
} else if (item.complexity.toLowerCase().includes('complex') || item.complexity.toLowerCase().includes('enterprise')) {
  complexityMultiplier = 1.45;
} else {
  complexityMultiplier = 1.15; // Moderate
}

const estimatedTotalHours = Math.round(baseHours * complexityMultiplier);

// Configurable standard agency rate ($50/hour base)
const standardHourlyRateUSD = 50;
const pkrExchangeRate = 278.50;

const expectedCostUSD = estimatedTotalHours * standardHourlyRateUSD;
const minCostUSD = Math.round(expectedCostUSD * 0.85);
const maxCostUSD = Math.round(expectedCostUSD * 1.30);

return [{
  json: {
    normalizedData: {
      ...item,
      baseHours,
      complexityMultiplier,
      estimatedTotalHours,
      standardHourlyRateUSD,
      expectedCostUSD,
      minCostUSD,
      maxCostUSD,
      expectedCostPKR: Math.round(expectedCostUSD * pkrExchangeRate),
      minCostPKR: Math.round(minCostUSD * pkrExchangeRate),
      maxCostPKR: Math.round(maxCostUSD * pkrExchangeRate)
    }
  }
}];

